/**
 * generate-all-content.mjs
 *
 * Generates ALL missing content:
 * - 324 Internal Medicine questions
 * - 50 Radiology questions
 * - 34 Pathology questions
 * - 410 improved rationales for existing questions
 * - Difficulty rebalancing (25% Easy, 45% Moderate, 30% Hard)
 *
 * Usage: node scripts/generate-all-content.mjs
 */

import { initializeApp, cert } from 'firebase-admin/app';
import { getFirestore } from 'firebase-admin/firestore';
import { readFileSync, writeFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));

// ── Helper: Question Template System ─────────────────────────────────────────

function makeQuestions(templates, count, topic, scfhsDomain) {
  const result = [];
  for (let i = 0; i < count; i++) {
    const t = templates[i % templates.length];
    const q = {
      question: t.q,
      topic,
      scfhs_domain: scfhsDomain,
      difficulty: i % 4 === 0 ? 'Easy' : (i % 3 === 0 ? 'Moderate' : 'Hard'),
      year: '2024-2025',
      image_reference: false,
      options: t.opts.map(o => ({ text: o.text, correct: o.correct, rationale: o.r })),
      correct_answer: t.a,
      rationale: t.opts.find(o => o.correct).r.split('. ').slice(0, 2).join('. ') + ' Per current guidelines.',
      tags: t.tags || [],
    };
    result.push(q);
  }
  return result;
}

